import type { Generated } from 'kysely';

/**
 * Row types for every table. Conventions (portable across SQLite, PostgreSQL, MySQL):
 * - ids are varchar(36) UUIDs generated by the app (no RETURNING needed)
 * - money is bigint satang, booleans are integer 0/1
 * - timestamps are ISO-8601 UTC strings; biz_date (YYYY-MM-DD) + hour are local business time
 * - JSON is stored as text
 */
export type Bool = number;

